      :root {
        color-scheme: light;
        --background: #f4f7fb;
        --card: #ffffff;
        --text: #172033;
        --muted: #687386;
        --border: #d9e1ec;
        --primary: #2563eb;
        --primary-dark: #1d4ed8;
        --ring: rgba(37, 99, 235, 0.18);
