        border: 1px solid rgba(217, 225, 236, 0.82);
        border-radius: 28px;
        background: rgba(255, 255, 255, 0.92);
        box-shadow: var(--shadow);
        backdrop-filter: blur(12px);
      }

      .eyebrow {
        display: inline-flex;
        margin: 0 0 14px;
        padding: 6px 12px;
        border-radius: 999px;
        color: var(--primary);
        background: rgba(37, 99, 235, 0.1);
        font-size: 0.78rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 5vw, 3rem);
        line-height: 1.04;
        letter-spacing: -0.045em;
      }

      .intro {
        margin: 16px 0 32px;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.65;
      }

      form {
        display: grid;
        gap: 20px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-size: 0.92rem;
        font-weight: 700;
      }

      input {
        width: 100%;
        min-height: 52px;
        border: 1px solid var(--border);
        border-radius: 16px;
        padding: 0 16px;
        color: var(--text);
        background: #ffffff;
        font: inherit;
        outline: none;
        transition:
          border-color 160ms ease,
          box-shadow 160ms ease,
          transform 160ms ease;
      }

      input::placeholder {
        color: #9aa5b5;
      }

      input:focus {
        border-color: var(--primary);
        box-shadow: 0 0 0 5px var(--ring);
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.86rem;
        line-height: 1.45;
      }

      .submit-button {
        min-height: 54px;
        margin-top: 4px;
        border: 0;
        border-radius: 16px;
        color: #ffffff;
        background: linear-gradient(135deg, var(--primary), #4f46e5);
        box-shadow: 0 14px 24px rgba(37, 99, 235, 0.26);
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        transition:
          background 160ms ease,
          box-shadow 160ms ease,
          transform 160ms ease;
      }

      .submit-button:hover {
        background: linear-gradient(135deg, var(--primary-dark), #4338ca);
        box-shadow: 0 18px 28px rgba(37, 99, 235, 0.32);
