          />
          ${helperText ? `<p class="helper-text">${helperText}</p>` : ""}
        </div>
      `;

      const ContactForm = () => `
        <main class="page-shell">
          <section class="support-card" aria-labelledby="support-title">
            <p class="eyebrow">Support</p>
            <h1 id="support-title">How can we help?</h1>
            <p class="intro">
              Send your contact details and our support team will get back to you shortly.
            </p>
            <form action="#" method="post">
              ${Field({
                id: "full-name",
                label: "Full name",
                required: true,
                placeholder: "Jordan Lee",
                autoComplete: "name",
