              ${Field({
                id: "email-address",
                label: "Email address",
                type: "email",
                required: true,
                placeholder: "jordan@example.com",
                autoComplete: "email",
              })}
              ${Field({
                id: "phone-number",
                label: "Phone number",
                type: "tel",
                placeholder: "(555) 123-4567",
                helperText: "Optional. Use a 10-digit phone number, such as (555) 123-4567.",
