 <!doctype html>
 <html lang="en">
   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Support Contact Form</title>
     <style>
       :root {
         color-scheme: light;
         --background: #f4f7fb;
         --card: #ffffff;
         --text: #172033;
         --muted: #687386;
         --border: #d9e1ec;
         --primary: #2563eb;
         --primary-dark: #1d4ed8;
         --ring: rgba(37, 99, 235, 0.18);
         --shadow: 0 24px 70px rgba(23, 32, 51, 0.12);
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family:
           Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
           "Segoe UI", sans-serif;
         color: var(--text);
         background:
           radial-gradient(circle at top left, rgba(37, 99, 235, 0.16), transparent 34rem),
           linear-gradient(135deg, #f8fbff 0%, var(--background) 100%);
       }

       .page-shell {
         display: grid;
         min-height: 100vh;
         place-items: center;
         padding: 48px 20px;
       }

       .support-card {
         width: min(100%, 540px);
         padding: 40px;
         border: 1px solid rgba(217, 225, 236, 0.82);
         border-radius: 28px;
         background: rgba(255, 255, 255, 0.92);
         box-shadow: var(--shadow);
         backdrop-filter: blur(12px);
       }

       .eyebrow {
         display: inline-flex;
         margin: 0 0 14px;
         padding: 6px 12px;
         border-radius: 999px;
         color: var(--primary);
         background: rgba(37, 99, 235, 0.1);
         font-size: 0.78rem;
         font-weight: 700;
         letter-spacing: 0.08em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 5vw, 3rem);
         line-height: 1.04;
         letter-spacing: -0.045em;
       }

       .intro {
         margin: 16px 0 32px;
         color: var(--muted);
         font-size: 1rem;
         line-height: 1.65;
       }

       form {
         display: grid;
         gap: 20px;
       }

       .form-field {
         display: grid;
         gap: 8px;
       }

       label {
         font-size: 0.92rem;
         font-weight: 700;
       }

       input {
         width: 100%;
         min-height: 52px;
         border: 1px solid var(--border);
         border-radius: 16px;
         padding: 0 16px;
         color: var(--text);
         background: #ffffff;
         font: inherit;
         outline: none;
         transition:
           border-color 160ms ease,
           box-shadow 160ms ease,
           transform 160ms ease;
       }

       input::placeholder {
         color: #9aa5b5;
       }

       input:focus {
         border-color: var(--primary);
         box-shadow: 0 0 0 5px var(--ring);
       }

       .helper-text {
         margin: 0;
         color: var(--muted);
         font-size: 0.86rem;
         line-height: 1.45;
       }

       .submit-button {
         min-height: 54px;
         margin-top: 4px;
         border: 0;
         border-radius: 16px;
         color: #ffffff;
         background: linear-gradient(135deg, var(--primary), #4f46e5);
         box-shadow: 0 14px 24px rgba(37, 99, 235, 0.26);
         cursor: pointer;
         font: inherit;
         font-weight: 800;
         transition:
           background 160ms ease,
           box-shadow 160ms ease,
           transform 160ms ease;
       }

       .submit-button:hover {
         background: linear-gradient(135deg, var(--primary-dark), #4338ca);
         box-shadow: 0 18px 28px rgba(37, 99, 235, 0.32);
         transform: translateY(-1px);
       }

       .submit-button:focus-visible {
         outline: 0;
         box-shadow:
           0 0 0 5px var(--ring),
           0 18px 28px rgba(37, 99, 235, 0.32);
       }

       @media (max-width: 560px) {
         .page-shell {
           padding: 24px 14px;
         }

         .support-card {
           padding: 28px 22px;
           border-radius: 22px;
         }
       }
     </style>
   </head>
   <body>
     <div id="root"></div>

     <script>
       const Field = ({ id, label, type = "text", required = false, placeholder, helperText, autoComplete }) => `
         <div class="form-field">
           <label for="${id}">${label}${required ? " *" : ""}</label>
           <input
             id="${id}"
             name="${id}"
             type="${type}"
             ${required ? "required" : ""}
             ${autoComplete ? `autocomplete="${autoComplete}"` : ""}
             ${placeholder ? `placeholder="${placeholder}"` : ""}
           />
           ${helperText ? `<p class="helper-text">${helperText}</p>` : ""}
         </div>
       `;

       const ContactForm = () => `
         <main class="page-shell">
           <section class="support-card" aria-labelledby="support-title">
             <p class="eyebrow">Support</p>
             <h1 id="support-title">How can we help?</h1>
             <p class="intro">
               Send your contact details and our support team will get back to you shortly.
             </p>
             <form action="#" method="post">
               ${Field({
                 id: "full-name",
                 label: "Full name",
                 required: true,
                 placeholder: "Jordan Lee",
                 autoComplete: "name",
               })}
               ${Field({
                 id: "email-address",
                 label: "Email address",
                 type: "email",
                 required: true,
                 placeholder: "jordan@example.com",
                 autoComplete: "email",
               })}
               ${Field({
                 id: "phone-number",
                 label: "Phone number",
                 type: "tel",
                 placeholder: "(555) 123-4567",
                 helperText: "Optional. Use a 10-digit phone number, such as (555) 123-4567.",
                 autoComplete: "tel",
               })}
               <button class="submit-button" type="submit">Submit request</button>
             </form>
           </section>
         </main>
       `;

       document.getElementById("root").innerHTML = ContactForm();
     </script>
   </body>
 </html>

